def resample_linear(values, positions):
    n = len(values)
    if n == 0:
        return []
    result = []
    for pos in positions:
        if pos < 0 or pos > n - 1:
            raise ValueError(f"Position {pos} out of range")
        if pos == n - 1:
            result.append(values[-1])
            continue
        lower = int(pos)
        upper = lower + 1
        if lower == pos:
            result.append(values[lower])
        else:
            weight = pos - lower
            interpolated = values[lower] + weight * (values[upper] - values[lower])
            result.append(interpolated)
    return result
